using System.Collections.ObjectModel;
namespace GraficaCaixa.Wpf;
public partial class AuditBackupWindow : System.Windows.Window
{
    int offset;bool auditBusy,auditEnd;readonly CancellationTokenSource lifetime=new();readonly GraficaCaixa.DataStore store; readonly ObservableCollection<AuditRow> audits=[]; readonly ObservableCollection<BackupRow> backups=[];
    public AuditBackupWindow(GraficaCaixa.DataStore store){InitializeComponent();BackupKeepText.Text=$"O sistema mantém as últimas {GraficaCaixa.BusinessRules.Current.InternalBackups} versões. Ao restaurar, o estado atual também é salvo como backup.";this.store=store;AuditGrid.ItemsSource=audits;BackupGrid.ItemsSource=backups;Loaded+=(_,_)=>LoadData();Closed+=(_,_)=>lifetime.Cancel();AuditGrid.AddHandler(System.Windows.Controls.ScrollViewer.ScrollChangedEvent,new System.Windows.Controls.ScrollChangedEventHandler(async (_,e)=>{if(store.IsRemote&&e.VerticalChange>0&&e.VerticalOffset+e.ViewportHeight>=e.ExtentHeight-60)await Page();}));}
    async Task Page(){if(auditBusy||auditEnd)return;auditBusy=true;try{var page=await store.QueryRemoteAsync<List<AuditEntry>>($"desktop/audit-summary?offset={offset}",lifetime.Token);lifetime.Token.ThrowIfCancellationRequested();offset+=page.Count;auditEnd=page.Count<100;foreach(var row in page)audits.Add(new AuditRow(row));}catch(OperationCanceledException){}catch(Exception ex){AlertWindow.Info(this,"Auditoria",ex.Message);}finally{auditBusy=false;}}
    async void LoadData(){if(auditBusy)return;try{audits.Clear();backups.Clear();offset=0;auditEnd=false;if(store.IsRemote){await Page();foreach(var x in await store.QueryRemoteAsync<List<BackupInfo>>("backups",lifetime.Token))backups.Add(new BackupRow(x));}else{foreach(var x in store.Load().AuditTrail.OrderByDescending(x=>x.Timestamp))audits.Add(new AuditRow(x));foreach(var x in store.ListBackups())backups.Add(new BackupRow(x));}}catch(OperationCanceledException) when(lifetime.IsCancellationRequested){/* saiu da tela durante a carga */}catch(Exception ex){if(!lifetime.IsCancellationRequested)AlertWindow.Info(this,"Backups",ex.Message);}}
    void Restore_Click(object sender,System.Windows.RoutedEventArgs e){if(BackupGrid.SelectedItem is not BackupRow row){AlertWindow.Info(this,"Selecione um backup","Escolha uma versão da lista para restaurar.");return;}if(!AlertWindow.Confirm(this,"Restaurar backup",$"Restaurar os dados de {row.Date}?\n\nO estado atual será salvo antes da restauração.",true))return;try{store.RestoreBackup(row.Path);LoadData();AlertWindow.Info(this,"Backup restaurado","Os dados foram recuperados. O outro computador receberá a atualização automaticamente.");}catch(Exception ex){AlertWindow.Info(this,"Não foi possível restaurar",ex.Message);}}
}
public sealed class AuditRow{public string Date{get;}public string Action{get;}public string Description{get;}public string Computer{get;}public string User{get;}public AuditRow(GraficaCaixa.AuditEntry x){Date=x.Timestamp.ToLocalTime().ToString("dd/MM/yyyy HH:mm:ss");Action=x.Action;Description=string.IsNullOrWhiteSpace(x.Description)?AuditNames.Named(x):x.Description;User=string.IsNullOrWhiteSpace(x.UserName)?"—":x.UserName;Computer=x.Computer;}}
public sealed class BackupRow{public string Path{get;}public string Date{get;}public string FileName{get;}public string Size{get;}public BackupRow(GraficaCaixa.BackupInfo x){Path=x.Path;Date=x.CreatedAt.ToString("dd/MM/yyyy HH:mm:ss");FileName=x.FileName;Size=x.Size<1024?$"{x.Size} B":$"{x.Size/1024d:N1} KB";}}
